using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text.RegularExpressions;

namespace WinTestKit.Inspector.Protocol
{
    public sealed class Diagnostic
    {
        public string Code { get; set; } = ""; public string Message { get; set; } = ""; public string? Category { get; set; }
        public JsonObjectNode ToJson() { var o = new JsonObjectNode(); DtoHelpers.Add(o, "code", Code); DtoHelpers.Add(o, "message", Message); DtoHelpers.Add(o, "category", Category); FromJson(o); return o; }
        public static Diagnostic FromJson(JsonNode n) { var o = DtoHelpers.Object(n, "code", "message", "category"); return new Diagnostic { Code = DtoHelpers.Required(o, "code"), Message = DtoHelpers.Required(o, "message", 1024, true), Category = DtoHelpers.Optional(o, "category") }; }
    }
    public sealed class ValueDto
    {
        public string Status { get; set; } = ""; public string Kind { get; set; } = ""; public string DeclaredType { get; set; } = ""; public string RuntimeType { get; set; } = ""; public JsonNode? Scalar { get; set; } public ObjectRef? Object { get; set; } public string? Message { get; set; } public long? TruncatedAt { get; set; } public ObjectRef? CycleTo { get; set; } public string? NumericValue { get; set; } public TypeInfoDto? TypeInfo { get; set; } public int? ArrayRank { get; set; } public long? ArrayLength { get; set; } public int? FailedSegment { get; set; } public string? RedactionRule { get; set; } public DependencySourceDto? DependencySource { get; set; }
        public JsonObjectNode ToJson() { var o = new JsonObjectNode(); DtoHelpers.Add(o, "status", Status); DtoHelpers.Add(o, "kind", Kind); DtoHelpers.Add(o, "declaredType", DeclaredType); DtoHelpers.Add(o, "runtimeType", RuntimeType); if (Scalar != null) o.Add("scalar", Scalar); if (Object != null) o.Add("object", Object.ToJson()); DtoHelpers.Add(o, "message", Message); DtoHelpers.Add(o, "truncatedAt", TruncatedAt); if (CycleTo != null) o.Add("cycleTo", CycleTo.ToJson()); DtoHelpers.Add(o, "numericValue", NumericValue); if (TypeInfo != null) o.Add("typeInfo", TypeInfo.ToJson()); DtoHelpers.Add(o, "arrayRank", ArrayRank); DtoHelpers.Add(o, "arrayLength", ArrayLength); DtoHelpers.Add(o, "failedSegment", FailedSegment); DtoHelpers.Add(o, "redactionRule", RedactionRule); if (DependencySource != null) o.Add("dependencySource", DependencySource.ToJson()); FromJson(o); return o; }
        public static ValueDto FromJson(JsonNode node)
        {
            var o = DtoHelpers.Object(node, "status", "kind", "declaredType", "runtimeType", "scalar", "object", "message", "truncatedAt", "cycleTo", "numericValue", "typeInfo", "arrayRank", "arrayLength", "failedSegment", "redactionRule", "dependencySource");
            var v = new ValueDto { Status = DtoHelpers.Required(o, "status"), Kind = DtoHelpers.Required(o, "kind"), DeclaredType = DtoHelpers.Required(o, "declaredType", 1024, true), RuntimeType = DtoHelpers.Required(o, "runtimeType", 1024, true), Message = DtoHelpers.Optional(o, "message", 1024, true), NumericValue = DtoHelpers.Optional(o, "numericValue", 1024), RedactionRule = DtoHelpers.Optional(o, "redactionRule", 1024) };
            DtoHelpers.OneOf(v.Status, ValueStatus.Ok, ValueStatus.NotRead, ValueStatus.NotReadable, ValueStatus.NullIntermediate, ValueStatus.Exception, ValueStatus.Stale, ValueStatus.Redacted, ValueStatus.Truncated, ValueStatus.Cycle, ValueStatus.Timeout, ValueStatus.Unsupported);
            DtoHelpers.OneOf(v.Kind, ValueKind.Null, ValueKind.String, ValueKind.Boolean, ValueKind.Integer, ValueKind.Number, ValueKind.Enum, ValueKind.Object, ValueKind.Array, ValueKind.Type, ValueKind.Unavailable);
            if (o.TryGet("dependencySource", out var source)) v.DependencySource = DependencySourceDto.FromJson(source);
            if (v.DependencySource != null && v.Status != ValueStatus.Ok && v.Status != ValueStatus.Truncated && v.Status != ValueStatus.Cycle) throw DtoHelpers.Invalid("Dependency source on unavailable value");
            if (o.TryGet("scalar", out var scalar)) v.Scalar = scalar; if (o.TryGet("object", out var obj)) v.Object = ObjectRef.FromJson(obj); if (o.TryGet("cycleTo", out var cycle)) v.CycleTo = ObjectRef.FromJson(cycle); if (o.TryGet("typeInfo", out var type)) v.TypeInfo = TypeInfoDto.FromJson(type);
            if (o.TryGet("truncatedAt", out var truncated)) v.TruncatedAt = DtoHelpers.Integer(truncated, 1); if (o.TryGet("failedSegment", out var failed)) v.FailedSegment = (int)DtoHelpers.Integer(failed, 0, ProtocolLimits.MaxPathSegments - 1); if (o.TryGet("arrayRank", out var rank)) v.ArrayRank = (int)DtoHelpers.Integer(rank, 1, int.MaxValue); if (o.TryGet("arrayLength", out var length)) v.ArrayLength = DtoHelpers.Integer(length);
            if (v.Status != ValueStatus.Ok && (v.NumericValue != null || v.ArrayRank != null || v.ArrayLength != null)) throw DtoHelpers.Invalid("Unavailable value contains data");
            if (v.RedactionRule != null && v.Status != ValueStatus.Redacted) throw DtoHelpers.Invalid("Redaction rule on non-redacted value");
            if (v.Status == ValueStatus.Ok && v.Kind != ValueKind.Array && (v.ArrayRank != null || v.ArrayLength != null)) throw DtoHelpers.Invalid("Array metadata on non-array value");
            if (v.Status == ValueStatus.Ok && v.Kind == ValueKind.Integer && v.Scalar is JsonStringNode integerString && !Regex.IsMatch(integerString.Value, @"^-?(0|[1-9][0-9]*)$")) throw DtoHelpers.Invalid("Invalid integer text");
            if (v.Status == ValueStatus.Ok && v.Kind == ValueKind.Enum && v.NumericValue != null && !Regex.IsMatch(v.NumericValue, @"^-?(0|[1-9][0-9]*)$")) throw DtoHelpers.Invalid("Invalid enum number");
            if (v.Status == ValueStatus.Ok && v.Kind == ValueKind.Number && v.Scalar is JsonStringNode numberString && numberString.Value != "NaN" && numberString.Value != "Infinity" && numberString.Value != "-Infinity" && !Regex.IsMatch(numberString.Value, @"^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$")) throw DtoHelpers.Invalid("Invalid number text");
            if (v.Status == ValueStatus.Ok) { if (v.CycleTo != null || v.TruncatedAt != null || v.FailedSegment != null || v.Kind == ValueKind.Unavailable) throw DtoHelpers.Invalid("Invalid ok value"); if (v.Kind == ValueKind.Object || v.Kind == ValueKind.Array) { if (v.Object == null || v.Scalar != null) throw DtoHelpers.Invalid("Object value requires object reference"); if (v.Kind == ValueKind.Array && (v.ArrayRank == null || v.ArrayLength == null)) throw DtoHelpers.Invalid("Array shape required"); } else if (v.Kind == ValueKind.Type) { if (v.TypeInfo == null || v.Object != null || v.Scalar != null) throw DtoHelpers.Invalid("Invalid type value"); } else { if (v.Scalar == null || v.Object != null) throw DtoHelpers.Invalid("Scalar value required"); if (v.Kind == ValueKind.Null && !(v.Scalar is JsonNullNode) || v.Kind == ValueKind.String && !(v.Scalar is JsonStringNode) || v.Kind == ValueKind.Boolean && !(v.Scalar is JsonBoolNode) || (v.Kind == ValueKind.Integer || v.Kind == ValueKind.Number) && !(v.Scalar is JsonNumberNode || v.Scalar is JsonStringNode) || v.Kind == ValueKind.Enum && !(v.Scalar is JsonStringNode)) throw DtoHelpers.Invalid("Wrong scalar kind"); if (v.Scalar is JsonStringNode s) DtoHelpers.String(s, ProtocolLimits.MaxScalarChars, true); if (v.Kind == ValueKind.Integer) { if (v.Scalar is JsonNumberNode integer && (!integer.TryGetInt64(out long i) || i < -9007199254740991L || i > 9007199254740991L)) throw DtoHelpers.Invalid("Invalid numeric integer"); if (v.Scalar is JsonStringNode integerText && !decimal.TryParse(integerText.Value, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out _)) throw DtoHelpers.Invalid("Invalid integer text"); } if (v.Kind == ValueKind.Enum && v.NumericValue == null) throw DtoHelpers.Invalid("Enum numeric value required"); } }
            else if (v.Status == ValueStatus.Truncated) { if (v.Kind != ValueKind.String || !(v.Scalar is JsonStringNode s) || v.TruncatedAt == null || v.Object != null || v.CycleTo != null || v.FailedSegment != null) throw DtoHelpers.Invalid("Invalid truncated value"); DtoHelpers.String(s, ProtocolLimits.MaxScalarChars, true); int scalarCount = 0; for (int i = 0; i < s.Value.Length; i++, scalarCount++) if (char.IsHighSurrogate(s.Value[i])) i++; if (v.TruncatedAt <= scalarCount) throw DtoHelpers.Invalid("Truncated length must exceed prefix"); }
            else if (v.Status == ValueStatus.Cycle) { if (v.CycleTo == null || v.Scalar != null || v.Object != null || v.TruncatedAt != null || v.FailedSegment != null) throw DtoHelpers.Invalid("Invalid cycle value"); }
            else { if (v.Kind != ValueKind.Unavailable || v.Scalar != null || v.Object != null || v.CycleTo != null || v.TruncatedAt != null || v.NumericValue != null) throw DtoHelpers.Invalid("Invalid unavailable value"); if ((v.Status == ValueStatus.NullIntermediate || v.Status == ValueStatus.Exception) != v.FailedSegment.HasValue) throw DtoHelpers.Invalid("Invalid failed segment"); }
            return v;
        }
    }
    public sealed class MappingDto
    {
        public string Status { get; set; } = ""; public ProcessIdentity Process { get; set; } = new ProcessIdentity(); public IReadOnlyList<int> RuntimeId { get; set; } = new List<int>(); public ObjectRef? Object { get; set; }
        public JsonObjectNode ToJson() { var o = new JsonObjectNode(); DtoHelpers.Add(o, "status", Status); o.Add("process", Process.ToJson()); o.Add("runtimeId", ResultHelpers.RuntimeId(RuntimeId)); if (Object != null) o.Add("object", Object.ToJson()); FromJson(o); return o; }
        public static MappingDto FromJson(JsonNode node) { var o = DtoHelpers.Object(node, "status", "process", "runtimeId", "object"); var x = new MappingDto { Status = DtoHelpers.Required(o, "status"), Process = ProcessIdentity.FromJson(o.Get("process")), RuntimeId = ResultHelpers.RuntimeId(o.Get("runtimeId")) }; DtoHelpers.OneOf(x.Status, MappingStatus.Exact, MappingStatus.NotFound, MappingStatus.Ambiguous, MappingStatus.UnsupportedPeer, MappingStatus.Stale, MappingStatus.LimitExceeded); if (o.TryGet("object", out var v)) x.Object = ObjectRef.FromJson(v); if ((x.Status == MappingStatus.Exact) != (x.Object != null)) throw DtoHelpers.Invalid("Invalid mapping variant"); return x; }
    }
    public sealed class ManagedNodeDto
    {
        public ObjectRef Object { get; set; } = new ObjectRef(); public string Label { get; set; } = ""; public bool HasVisualChildren { get; set; } public bool HasLogicalChildren { get; set; } public IReadOnlyList<int>? RuntimeId { get; set; }
        public JsonObjectNode ToJson() { var o = new JsonObjectNode(); o.Add("object", Object.ToJson()); DtoHelpers.Add(o, "label", Label); o.Add("hasVisualChildren", new JsonBoolNode(HasVisualChildren)); o.Add("hasLogicalChildren", new JsonBoolNode(HasLogicalChildren)); if (RuntimeId != null) o.Add("runtimeId", ResultHelpers.RuntimeId(RuntimeId)); FromJson(o); return o; }
        public static ManagedNodeDto FromJson(JsonNode node) { var o = DtoHelpers.Object(node, "object", "label", "hasVisualChildren", "hasLogicalChildren", "runtimeId"); return new ManagedNodeDto { Object = ObjectRef.FromJson(o.Get("object")), Label = DtoHelpers.Required(o, "label", 1024, true), HasVisualChildren = DtoHelpers.Boolean(o.Get("hasVisualChildren")), HasLogicalChildren = DtoHelpers.Boolean(o.Get("hasLogicalChildren")), RuntimeId = o.TryGet("runtimeId", out var id) ? ResultHelpers.RuntimeId(id) : null }; }
    }
    internal static class ResultHelpers
    {
        internal static JsonArrayNode RuntimeId(IEnumerable<int> id) { var a = new JsonArrayNode(); foreach (int i in id) a.Add(JsonNumberNode.From(i)); return a; }
        internal static IReadOnlyList<int> RuntimeId(JsonNode node) { var result = new List<int>(); foreach (var n in DtoHelpers.Array(node, 1024).Items) result.Add((int)DtoHelpers.Integer(n, int.MinValue, int.MaxValue)); if (result.Count == 0) throw DtoHelpers.Invalid("Empty runtime ID"); return result; }
        internal static JsonArrayNode Path(IEnumerable<PathSegment> path) { var a = new JsonArrayNode(); foreach (var s in path) a.Add(s.ToJson()); return a; }
        internal static IReadOnlyList<PathSegment> Path(JsonNode node) { var result = new List<PathSegment>(); foreach (var n in DtoHelpers.Array(node, ProtocolLimits.MaxPathSegments).Items) result.Add(PathSegment.FromJson(n)); if (result.Count == 0 || (result.Count > 1 && result.Exists(x => (x.Kind == SegmentKind.Type || x.Kind == "uia"))) || StrictJson.Serialize(node).Length > ProtocolLimits.MaxPathBytes) throw DtoHelpers.Invalid("Invalid path"); return result; }
    }
    public sealed class PageDto<T>
    {
        public IReadOnlyList<T> Items { get; set; } = new List<T>(); public bool Complete { get; set; } public string SnapshotId { get; set; } = ""; public IReadOnlyList<Diagnostic> Diagnostics { get; set; } = new List<Diagnostic>(); public string? NextToken { get; set; }
        public JsonObjectNode ToJson() { var o = new JsonObjectNode(); var items = new JsonArrayNode(); foreach (var item in Items) { if (item is ManagedNodeDto n) items.Add(n.ToJson()); else if (item is MemberInfo m) items.Add(m.ToJson()); else throw DtoHelpers.Invalid("Unsupported page item"); } o.Add("items", items); o.Add("complete", new JsonBoolNode(Complete)); DtoHelpers.Add(o, "snapshotId", SnapshotId); var diagnostics = new JsonArrayNode(); foreach (var d in Diagnostics) diagnostics.Add(d.ToJson()); o.Add("diagnostics", diagnostics); DtoHelpers.Add(o, "nextToken", NextToken); return o; }
        public static PageDto<T> FromJson(JsonNode node, Func<JsonNode, T> reader) { var o = DtoHelpers.Object(node, "items", "complete", "snapshotId", "diagnostics", "nextToken"); var items = new List<T>(); foreach (var n in DtoHelpers.Array(o.Get("items")).Items) items.Add(reader(n)); var diagnostics = new List<Diagnostic>(); foreach (var n in DtoHelpers.Array(o.Get("diagnostics")).Items) diagnostics.Add(Diagnostic.FromJson(n)); var x = new PageDto<T> { Items = items, Complete = DtoHelpers.Boolean(o.Get("complete")), SnapshotId = DtoHelpers.Required(o, "snapshotId"), Diagnostics = diagnostics, NextToken = DtoHelpers.Optional(o, "nextToken") }; if (x.Complete && x.NextToken != null) throw DtoHelpers.Invalid("Complete page cannot have next token"); return x; }
    }
}
